<script lang="ts">
  import { goto } from '$app/navigation'; import { onMount } from 'svelte';
  import { getOperationsSummary, listConnectors, listPipelineDefinitions, pipelineErrorMessage, type ConnectorDefinition, type NexetlError, type OperationsSummary, type PipelineDefinition } from '$lib/api/pipelines'; import { formatTimestamp } from '$lib/format';
