  onMount(async () => { try { const [all, draft, old, catalogue, latest, operational] = await Promise.all([listPipelineDefinitions({ pageSize: 1 }), listPipelineDefinitions({ pageSize: 1, state: 'DRAFT' }), listPipelineDefinitions({ pageSize: 1, state: 'ARCHIVED' }), listConnectors(), listPipelineDefinitions({ pageSize: 5, sort: '-updatedAt' }),getOperationsSummary()]); total = all.totalItems; drafts = draft.totalItems; archived = old.totalItems; connectors = catalogue.items.filter((item) => item.availability === 'AVAILABLE'); recent = latest.items; operations=operational; } catch (failure) { error = pipelineErrorMessage(failure as NexetlError); } finally { loading = false; } });
</script>
